package com.campusvibe.controller; import com.campusvibe.entity.*; import com.campusvibe.repository.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/public") public class PublicController {final EventRepository e;final AnnouncementRepository a;final CategoryRepository c;final VenueRepository v;final SponsorRepository s;final ResultRepository r; public PublicController(EventRepository e,AnnouncementRepository a,CategoryRepository c,VenueRepository v,SponsorRepository s,ResultRepository r){this.e=e;this.a=a;this.c=c;this.v=v;this.s=s;this.r=r;} @GetMapping("/events") public List<Event> events(){return e.findAll();} @GetMapping("/announcements") public List<Announcement> announcements(){return a.findAll();} @GetMapping("/categories") public List<Category> categories(){return c.findAll();} @GetMapping("/venues") public List<Venue> venues(){return v.findAll();} @GetMapping("/sponsors") public List<Sponsor> sponsors(){return s.findAll();} @GetMapping("/results") public List<Result> results(){return r.findAll().stream().filter(x->x.published).toList();}}
